def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        pts = {(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == color}
        for r,c in list(pts):
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                nr,nc=r+dr,c+dc
                if (nr,nc) not in pts:
                    continue
                # Extend beyond the far endpoint of each observed diagonal segment.
                for sr,sc in ((r-dr,c-dc),(nr+dr,nc+dc)):
                    rr,cc=sr,sc
                    while 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg:
                        out[rr][cc]=color
                        rr+=dr;cc+=dc
    return out
